  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","title","tear","spread","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "Make it yours.",
  tear: 34,
  spread: 0.205,
  accent: "#3B5BFD",
  fontFamily: "Bricolage Grotesque",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type TornEdgeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TornEdgeBase>;

const TornEdgeInner = forwardRef<
  HTMLDivElement,
  TornEdgeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TornEdge>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TornEdgeBase
          {...(componentProps as unknown as ComponentProps<typeof TornEdgeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TornEdge = Interactive.withSchema({
  Component: TornEdgeInner,
  componentName: "<TornEdge>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
